'use client';

import { ark, type HTMLArkProps } from '@ark-ui/react/factory';
import { Popover as PopoverPrimitive, usePopover, usePopoverContext } from '@ark-ui/react/popover';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import {
  OverlayPortal,
  OverlayPortalProvider,
  type OverlayPortalProps,
} from '@/lib/moduix/overlayPortal';
import { CloseButton } from '../close-button';
import styles from './Popover.module.css';

export type PopoverRootProps = ComponentProps<typeof PopoverPrimitive.Root> & OverlayPortalProps;
export type PopoverRootProviderProps = ComponentProps<typeof PopoverPrimitive.RootProvider> &
  Pick<OverlayPortalProps, 'portalRef'>;

function Popover({
  lazyMount = true,
  modal,
  portalled,
  portalRef,
  unmountOnExit = true,
  ...props
}: PopoverRootProps) {
  const resolvedPortalled = modal || portalled;

  return (
    <OverlayPortalProvider portalled={resolvedPortalled} portalRef={portalRef}>
      <PopoverPrimitive.Root
        lazyMount={lazyMount}
        modal={modal}
        portalled={resolvedPortalled}
        unmountOnExit={unmountOnExit}
        {...props}
      />
    </OverlayPortalProvider>
  );
}

function PopoverRootProvider({
  lazyMount = true,
  portalRef,
  unmountOnExit = true,
  value,
  ...props
}: PopoverRootProviderProps) {
  return (
    <OverlayPortalProvider portalled={value.portalled} portalRef={portalRef}>
      <PopoverPrimitive.RootProvider
        value={value}
        lazyMount={lazyMount}
        unmountOnExit={unmountOnExit}
        {...props}
      />
    </OverlayPortalProvider>
  );
}

const PopoverAnchor = forwardRef<
  ComponentRef<typeof PopoverPrimitive.Anchor>,
  ComponentProps<typeof PopoverPrimitive.Anchor>
>(function PopoverAnchor(props, ref) {
  return <PopoverPrimitive.Anchor ref={ref} {...props} data-slot="popover-anchor" />;
});

const PopoverTrigger = forwardRef<
  ComponentRef<typeof PopoverPrimitive.Trigger>,
  ComponentProps<typeof PopoverPrimitive.Trigger>
>(function PopoverTrigger({ asChild, className, ...props }, ref) {
  return (
    <PopoverPrimitive.Trigger
      ref={ref}
      asChild={asChild}
      className={clsx(!asChild && styles.trigger, className)}
      {...props}
      data-slot="popover-trigger"
    />
  );
});

const PopoverIndicator = forwardRef<
  ComponentRef<typeof PopoverPrimitive.Indicator>,
  ComponentProps<typeof PopoverPrimitive.Indicator>
>(function PopoverIndicator(props, ref) {
  return <PopoverPrimitive.Indicator ref={ref} {...props} data-slot="popover-indicator" />;
});

const PopoverPositioner = forwardRef<
  ComponentRef<typeof PopoverPrimitive.Positioner>,
  ComponentProps<typeof PopoverPrimitive.Positioner>
>(function PopoverPositioner({ className, ...props }, ref) {
  return (
    <OverlayPortal>
      <PopoverPrimitive.Positioner
        ref={ref}
        className={clsx(styles.positioner, className)}
        {...props}
        data-slot="popover-positioner"
      />
    </OverlayPortal>
  );
});

const PopoverContent = forwardRef<
  ComponentRef<typeof PopoverPrimitive.Content>,
  ComponentProps<typeof PopoverPrimitive.Content>
>(function PopoverContent({ className, ...props }, ref) {
  return (
    <PopoverPrimitive.Content
      ref={ref}
      className={clsx(styles.content, className)}
      {...props}
      data-slot="popover-content"
    />
  );
});

const PopoverArrow = forwardRef<
  ComponentRef<typeof PopoverPrimitive.Arrow>,
  ComponentProps<typeof PopoverPrimitive.Arrow>
>(function PopoverArrow({ className, children, ...props }, ref) {
  return (
    <PopoverPrimitive.Arrow
      ref={ref}
      className={clsx(styles.arrow, className)}
      {...props}
      data-slot="popover-arrow"
    >
      {children ?? <PopoverArrowTip />}
    </PopoverPrimitive.Arrow>
  );
});

const PopoverArrowTip = forwardRef<
  ComponentRef<typeof PopoverPrimitive.ArrowTip>,
  ComponentProps<typeof PopoverPrimitive.ArrowTip>
>(function PopoverArrowTip({ className, ...props }, ref) {
  return (
    <PopoverPrimitive.ArrowTip
      ref={ref}
      className={clsx(styles.arrowTip, className)}
      {...props}
      data-slot="popover-arrow-tip"
    />
  );
});

const PopoverTitle = forwardRef<
  ComponentRef<typeof PopoverPrimitive.Title>,
  ComponentProps<typeof PopoverPrimitive.Title>
>(function PopoverTitle({ className, ...props }, ref) {
  return (
    <PopoverPrimitive.Title
      ref={ref}
      className={clsx(styles.title, className)}
      {...props}
      data-slot="popover-title"
    />
  );
});

const PopoverDescription = forwardRef<
  ComponentRef<typeof PopoverPrimitive.Description>,
  ComponentProps<typeof PopoverPrimitive.Description>
>(function PopoverDescription({ className, ...props }, ref) {
  return (
    <PopoverPrimitive.Description
      ref={ref}
      className={clsx(styles.description, className)}
      {...props}
      data-slot="popover-description"
    />
  );
});

const PopoverCloseTrigger = forwardRef<
  ComponentRef<typeof PopoverPrimitive.CloseTrigger>,
  ComponentProps<typeof PopoverPrimitive.CloseTrigger>
>(function PopoverCloseTrigger({ asChild, className, ...props }, ref) {
  return (
    <PopoverPrimitive.CloseTrigger
      ref={ref}
      asChild={asChild}
      className={clsx(!asChild && styles.closeTrigger, className)}
      {...props}
      data-slot="popover-close-trigger"
    />
  );
});

const PopoverCloseIcon = forwardRef<
  ComponentRef<typeof CloseButton>,
  Omit<ComponentProps<typeof PopoverPrimitive.CloseTrigger>, 'asChild'>
>(function PopoverCloseIcon(
  { className, children, 'aria-label': ariaLabel = a11yLabels.closePopover, ...props },
  ref,
) {
  return (
    <PopoverPrimitive.CloseTrigger asChild {...props}>
      <CloseButton
        ref={ref}
        data-slot="popover-close-icon"
        aria-label={ariaLabel}
        className={clsx(styles.closeIcon, className)}
      >
        {children}
      </CloseButton>
    </PopoverPrimitive.CloseTrigger>
  );
});

const PopoverHeader = forwardRef<ComponentRef<typeof ark.div>, HTMLArkProps<'div'>>(
  function PopoverHeader({ className, ...props }, ref) {
    return (
      <ark.div
        ref={ref}
        className={clsx(styles.header, className)}
        {...props}
        data-slot="popover-header"
      />
    );
  },
);

const PopoverBody = forwardRef<ComponentRef<typeof ark.div>, HTMLArkProps<'div'>>(
  function PopoverBody({ className, ...props }, ref) {
    return (
      <ark.div
        ref={ref}
        className={clsx(styles.body, className)}
        {...props}
        data-slot="popover-body"
      />
    );
  },
);

const PopoverFooter = forwardRef<ComponentRef<typeof ark.div>, HTMLArkProps<'div'>>(
  function PopoverFooter({ className, ...props }, ref) {
    return (
      <ark.div
        ref={ref}
        className={clsx(styles.footer, className)}
        {...props}
        data-slot="popover-footer"
      />
    );
  },
);

const PopoverContext = PopoverPrimitive.Context;

export {
  Popover,
  PopoverAnchor,
  PopoverArrow,
  PopoverArrowTip,
  PopoverBody,
  PopoverCloseIcon,
  PopoverCloseTrigger,
  PopoverContent,
  PopoverContext,
  PopoverDescription,
  PopoverFooter,
  PopoverHeader,
  PopoverIndicator,
  PopoverPositioner,
  PopoverRootProvider,
  PopoverTitle,
  PopoverTrigger,
  usePopover,
  usePopoverContext,
};

export type {
  PopoverAnchorProps,
  PopoverArrowProps,
  PopoverArrowTipProps,
  PopoverCloseTriggerProps,
  PopoverContentProps,
  PopoverContextProps,
  PopoverDescriptionProps,
  PopoverFocusOutsideEvent,
  PopoverIndicatorProps,
  PopoverInteractOutsideEvent,
  PopoverOpenChangeDetails,
  PopoverPointerDownOutsideEvent,
  PopoverPositionerProps,
  PopoverTitleProps,
  PopoverTriggerProps,
  PopoverTriggerValueChangeDetails,
  UsePopoverContext,
  UsePopoverProps,
  UsePopoverReturn,
} from '@ark-ui/react/popover';

@layer moduix.components {
  .trigger,
  .closeTrigger {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: var(--moduix-size-md);
    margin: 0;
    padding: var(--moduix-spacing-1) var(--moduix-spacing-3-5);
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    font: inherit;
    font-size: var(--moduix-text-md);
    line-height: var(--moduix-line-height-text-md);
    user-select: none;
    outline: 0;
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-default),
      border-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-color-accent);
      }
    }

    &:active,
    &[data-state='open']:not([data-value]),
    &[data-state='open'][data-current] {
      background-color: var(--moduix-color-accent);
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: calc(var(--moduix-focus-ring-inset-width) * -1);
    }

    &:disabled {
      pointer-events: none;
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .positioner {
    z-index: var(--z-index, var(--moduix-z-popup));
    max-width: var(--available-width);
    outline: 0;
  }

  .content {
    position: relative;
    z-index: calc(var(--moduix-z-popup) + var(--layer-index, 0));
    box-sizing: border-box;
    min-width: min(16rem, var(--available-width));
    max-width: min(28rem, var(--available-width));
    max-height: min(24rem, var(--available-height, 100dvh));
    overflow-wrap: anywhere;
    padding: var(--moduix-spacing-4);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-popover);
    color: var(--moduix-color-popover-foreground);
    outline: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    box-shadow: var(--moduix-shadow-lg);
    transform-origin: var(--transform-origin);

    /* Lets PopoverBody scroll within the height limit while the surface stays overflow-visible for the arrow. */
    &:has(> .body) {
      display: flex;
      flex-direction: column;
    }

    &[data-state='open'] {
      animation: global(moduix-popup-in)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out));
    }

    &[data-state='closed'] {
      animation: global(moduix-popup-out)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out)) forwards;
    }
  }

  .arrow {
    --arrow-size: var(--moduix-spacing-2-5);
    --arrow-background: var(--moduix-color-popover);
  }

  .arrowTip {
    border-top: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-left: var(--moduix-border-width-sm) solid var(--moduix-color-border);
  }

  .header {
    display: grid;
    gap: var(--moduix-spacing-1);

    /* Keeps the title clear of the absolutely positioned close icon. */
    .content:has(.closeIcon) & {
      padding-inline-end: calc(var(--moduix-spacing-7) + var(--moduix-spacing-3));
    }
  }

  .title {
    margin: 0;
    font-size: var(--moduix-text-md);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-md);
  }

  .description {
    margin: 0;
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
  }

  .body {
    min-block-size: 0;
    overflow: auto;

    .header + & {
      margin-block-start: var(--moduix-spacing-3);
    }
  }

  .footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: var(--moduix-spacing-2);
    margin-block-start: var(--moduix-spacing-3);
  }

  .closeIcon {
    --moduix-close-button-bg-hover: var(--moduix-color-accent);
    --moduix-close-button-color-hover: var(--moduix-color-popover-foreground);
    position: absolute;
    inset-block-start: var(--moduix-spacing-3);
    inset-inline-end: var(--moduix-spacing-3);
  }

  @media (prefers-reduced-motion: reduce) {
    .trigger,
    .closeTrigger {
      transition: none;
    }

    .content[data-state] {
      animation: none;
    }
  }
}
